package cn.binbin.crm;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.validation.constraints.*;
import java.security.MessageDigest;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import java.util.function.Function;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;

@Service
public class PortalService {
 public record TicketInput(@NotBlank @Size(max=200) String title,@Size(max=10000) String description,@NotNull @Pattern(regexp="URGENT|HIGH|NORMAL|LOW") String priority,@NotBlank @Pattern(regexp="[A-Z0-9_]{1,40}") String typeCode){}
 public record CommentInput(@Min(0) long expectedVersion,@NotBlank @Size(max=4000) String body){}
 public record Page<T>(List<T> items,int page,int pageSize,long total){}
 private final NamedParameterJdbcTemplate db;private final TransactionTemplate tx;private final PortalAuthService auth;private final ObjectMapper json;private final QuotePdf pdf;private final ObjectStore storage;
 public PortalService(NamedParameterJdbcTemplate db,TransactionTemplate tx,PortalAuthService auth,ObjectMapper json,QuotePdf pdf,ObjectStore storage){this.db=db;this.tx=tx;this.auth=auth;this.json=json;this.pdf=pdf;this.storage=storage;}
 private static Map<String,Object> p(Object... v){return SaasService.parameters(v);}private static String text(String s){return s==null?"":s.strip();}
 private void page(int page,int size,String q){if(page<1||page>100000||size<1||size>100||q==null||q.length()>100)throw ApiError.bad("分页或搜索条件无效");}
 private <T>T scoped(PortalAuthService.Context c,boolean write,Function<PortalAuthService.Context,T> fn){return tx.execute(st->{if(c.mustChangePassword())throw new ApiError(org.springframework.http.HttpStatus.FORBIDDEN,"PORTAL_PASSWORD_CHANGE_REQUIRED","首次登录请先修改初始密码");if(write)db.queryForObject("SELECT id FROM sys_tenant WHERE id=:tenant FOR UPDATE",p("tenant",c.tenantId()),UUID.class);db.queryForObject("SELECT set_config('crm.tenant_id',:tenant,true)",p("tenant",c.tenantId().toString()),String.class);return fn.apply(c);});}
 private List<Map<String,Object>> rows(String sql,Map<String,?> p){return db.queryForList(sql,p).stream().map(SaasService::view).toList();}
 private Map<String,Object> one(String sql,Map<String,?> p){var r=db.queryForList(sql,p);if(r.isEmpty())throw ApiError.missing();return r.getFirst();}
 private String body(Object o){try{return json.writeValueAsString(o);}catch(Exception e){throw new IllegalStateException(e);}}
 private Map<String,Object> object(Object o){try{return json.readValue(String.valueOf(o),new TypeReference<>(){});}catch(Exception e){throw new IllegalStateException(e);}}
 public Object summary(PortalAuthService.Context c){return scoped(c,false,x->{var q=p("tenant",x.tenantId(),"customer",x.customerId());return p("customer",SaasService.view(one("SELECT id,customer_name AS name,industry,level_code,region FROM crm_customer WHERE tenant_id=:tenant AND id=:customer",q)),"counts",p("quotes",db.queryForObject("SELECT count(*) FROM crm_quote WHERE tenant_id=:tenant AND customer_id=:customer AND status='APPROVED'",q,Long.class),"contracts",db.queryForObject("SELECT count(*) FROM crm_contract WHERE tenant_id=:tenant AND customer_id=:customer AND status IN('SIGNED','ACTIVE','TERMINATED')",q,Long.class),"receipts",db.queryForObject("SELECT count(*) FROM crm_receipt WHERE tenant_id=:tenant AND customer_id=:customer AND status IN('CONFIRMED','REVERSED')",q,Long.class),"tickets",db.queryForObject("SELECT count(*) FROM crm_ticket WHERE tenant_id=:tenant AND customer_id=:customer",q,Long.class)),"storageConfigured",storage.configured());});}
 public Object quotes(PortalAuthService.Context c,int page,int size,String q){page(page,size,q);return scoped(c,false,x->{var v=p("tenant",x.tenantId(),"customer",x.customerId(),"q",text(q).toLowerCase(Locale.ROOT),"limit",size,"offset",((long)page-1)*size);String where="tenant_id=:tenant AND customer_id=:customer AND status='APPROVED' AND(:q='' OR strpos(lower(title),:q)>0 OR strpos(lower(quote_number),:q)>0)";return new Page<>(rows("SELECT id,quote_number,title,status,valid_until,total_cents,currency,version,updated_at FROM crm_quote WHERE "+where+" ORDER BY updated_at DESC,id LIMIT :limit OFFSET :offset",v),page,size,db.queryForObject("SELECT count(*) FROM crm_quote WHERE "+where,v,Long.class));});}
 public Object quote(PortalAuthService.Context c,UUID id){return scoped(c,false,x->{var q=SaasService.view(one("SELECT id,quote_number,title,status,valid_until,total_cents,currency,version,notes,company_name_snapshot,customer_name_snapshot,owner_name_snapshot,opportunity_title_snapshot FROM crm_quote WHERE tenant_id=:tenant AND customer_id=:customer AND id=:id AND status='APPROVED'",p("tenant",x.tenantId(),"customer",x.customerId(),"id",id)));q.put("lines",rows("SELECT line_number,sku_snapshot,name_snapshot,unit_snapshot,quantity,unit_price_cents,discount_bps,amount_cents,description FROM crm_quote_line WHERE tenant_id=:tenant AND quote_id=:id ORDER BY line_number",p("tenant",x.tenantId(),"id",id)));auth.audit(x,"QUOTE_VIEWED","QUOTE",id,UUID.randomUUID());return q;});}
 public byte[] quotePdf(PortalAuthService.Context c,UUID id){@SuppressWarnings("unchecked")var q=(Map<String,Object>)quote(c,id);byte[] data=pdf.render(q);auth.audit(c,"QUOTE_PDF_DOWNLOADED","QUOTE",id,UUID.randomUUID());return data;}
 public Object contracts(PortalAuthService.Context c,int page,int size,String q){page(page,size,q);return scoped(c,false,x->{var v=p("tenant",x.tenantId(),"customer",x.customerId(),"q",text(q).toLowerCase(Locale.ROOT),"limit",size,"offset",((long)page-1)*size);String where="tenant_id=:tenant AND customer_id=:customer AND status IN('SIGNED','ACTIVE','TERMINATED') AND(:q='' OR strpos(lower(title),:q)>0 OR strpos(lower(contract_number),:q)>0)";return new Page<>(rows("SELECT id,contract_number,title,status,total_cents,currency,start_date,end_date,signed_date,effective_date,version,updated_at FROM crm_contract WHERE "+where+" ORDER BY updated_at DESC,id LIMIT :limit OFFSET :offset",v),page,size,db.queryForObject("SELECT count(*) FROM crm_contract WHERE "+where,v,Long.class));});}
 public Object contract(PortalAuthService.Context c,UUID id){return scoped(c,false,x->{var q=p("tenant",x.tenantId(),"customer",x.customerId(),"id",id);var k=SaasService.view(one("SELECT id,contract_number,title,status,total_cents,currency,start_date,end_date,signed_date,effective_date,termination_reason,notes,version,updated_at FROM crm_contract WHERE tenant_id=:tenant AND customer_id=:customer AND id=:id AND status IN('SIGNED','ACTIVE','TERMINATED')",q));k.put("plans",rows("SELECT id,line_number,title,amount_cents,due_date FROM crm_collection_plan WHERE tenant_id=:tenant AND contract_id=:id AND active ORDER BY line_number",q));return k;});}
 public Object receipts(PortalAuthService.Context c,int page,int size,String q){page(page,size,q);return scoped(c,false,x->{var v=p("tenant",x.tenantId(),"customer",x.customerId(),"q",text(q).toLowerCase(Locale.ROOT),"limit",size,"offset",((long)page-1)*size);String where="tenant_id=:tenant AND customer_id=:customer AND status IN('CONFIRMED','REVERSED') AND(:q='' OR strpos(lower(receipt_number),:q)>0 OR strpos(lower(contract_number_snapshot),:q)>0 OR strpos(lower(payment_reference),:q)>0)";return new Page<>(rows("SELECT id,receipt_number,contract_id,contract_number_snapshot,plan_title_snapshot,amount_cents,received_date,payment_reference,payer_name,bank_name,status,confirmed_at,version FROM crm_receipt WHERE "+where+" ORDER BY received_date DESC,id LIMIT :limit OFFSET :offset",v),page,size,db.queryForObject("SELECT count(*) FROM crm_receipt WHERE "+where,v,Long.class));});}
 public Object tickets(PortalAuthService.Context c,int page,int size,String q){page(page,size,q);return scoped(c,false,x->{var v=p("tenant",x.tenantId(),"customer",x.customerId(),"q",text(q).toLowerCase(Locale.ROOT),"limit",size,"offset",((long)page-1)*size);String where="tenant_id=:tenant AND customer_id=:customer AND(:q='' OR strpos(lower(title),:q)>0 OR strpos(lower(ticket_number),:q)>0)";return new Page<>(rows("SELECT id,ticket_number,title,type_code,priority,status,resolution,version,created_at,updated_at FROM crm_ticket WHERE "+where+" ORDER BY updated_at DESC,id LIMIT :limit OFFSET :offset",v),page,size,db.queryForObject("SELECT count(*) FROM crm_ticket WHERE "+where,v,Long.class));});}
 private Map<String,Object> ticket(PortalAuthService.Context c,UUID id){var t=SaasService.view(one("SELECT id,ticket_number,title,description,type_code,priority,status,resolution,version,created_at,updated_at FROM crm_ticket WHERE tenant_id=:tenant AND customer_id=:customer AND id=:id",p("tenant",c.tenantId(),"customer",c.customerId(),"id",id)));t.put("comments",rows("SELECT id,body,kind,actor_name_snapshot,portal_account_id IS NOT NULL AS customer_reply,created_at FROM crm_ticket_comment WHERE tenant_id=:tenant AND ticket_id=:id AND kind='PUBLIC_REPLY' ORDER BY created_at,id",p("tenant",c.tenantId(),"id",id)));t.put("attachments",rows("SELECT id,file_name,content_type,size_bytes,sha256,uploaded_by_portal_account_id IS NOT NULL AS customer_upload,created_at FROM crm_attachment WHERE tenant_id=:tenant AND ticket_id=:id AND status='READY' ORDER BY created_at,id",p("tenant",c.tenantId(),"id",id)));var sla=rows("SELECT cycle_no,state,first_response_due_at,resolution_due_at,first_response_at,resolved_at,response_breached_at,resolution_breached_at FROM crm_ticket_sla_episode WHERE tenant_id=:tenant AND ticket_id=:id ORDER BY cycle_no DESC LIMIT 1",p("tenant",c.tenantId(),"id",id));t.put("sla",sla.isEmpty()?null:sla.getFirst());return t;}
 public Object ticket(PortalAuthService.Context c,UUID id,boolean audit){return scoped(c,false,x->{var t=ticket(x,id);if(audit)auth.audit(x,"TICKET_VIEWED","TICKET",id,UUID.randomUUID());return t;});}
 private UUID once(PortalAuthService.Context c,String operation,String key,Object input,java.util.function.Supplier<UUID> fn){if(key==null||!key.matches("[A-Za-z0-9_.:-]{1,100}"))throw ApiError.bad("请求编号无效");String hash=Crypto.hash(body(input));var q=p("account",c.accountId(),"op",operation,"key",key,"hash",hash);db.update("INSERT INTO portal_idempotency(account_id,operation,request_key,request_hash) VALUES(:account,:op,:key,:hash) ON CONFLICT DO NOTHING",q);var r=one("SELECT request_hash,result_id FROM portal_idempotency WHERE account_id=:account AND operation=:op AND request_key=:key FOR UPDATE",q);if(!hash.equals(r.get("request_hash")))throw ApiError.conflict("相同请求编号对应的内容已变化");if(r.get("result_id")!=null)return (UUID)r.get("result_id");UUID id=fn.get();q.put("result",id);db.update("UPDATE portal_idempotency SET result_id=:result WHERE account_id=:account AND operation=:op AND request_key=:key",q);return id;}
 private Map<String,Object> builtinSla(){return p("name","内置自然时间 SLA","pauseWaiting",true,"escalate",true,"targets",List.of(p("priority","URGENT","responseMinutes",60,"resolutionMinutes",480),p("priority","HIGH","responseMinutes",240,"resolutionMinutes",1440),p("priority","NORMAL","responseMinutes",480,"resolutionMinutes",4320),p("priority","LOW","responseMinutes",1440,"resolutionMinutes",10080)));}
 @SuppressWarnings("unchecked") private int minutes(Map<String,Object> sla,String priority,String key){for(Object raw:(List<?>)sla.get("targets")){var m=(Map<String,Object>)raw;if(priority.equals(m.get("priority")))return ((Number)m.get(key)).intValue();}throw ApiError.bad("SLA 配置不完整");}
 private UUID assignee(PortalAuthService.Context c){var ids=db.queryForList("SELECT m.id FROM sys_tenant_member m JOIN iam_user u ON u.id=m.user_id WHERE m.tenant_id=:tenant AND m.status='ACTIVE' AND u.status='ACTIVE' AND NOT u.must_change_password AND EXISTS(SELECT 1 FROM sys_member_role r JOIN sys_role_policy p ON p.tenant_id=r.tenant_id AND p.role_code=r.role_code WHERE r.tenant_id=m.tenant_id AND r.member_id=m.id AND p.ticket_can_write) ORDER BY EXISTS(SELECT 1 FROM sys_member_role r WHERE r.tenant_id=m.tenant_id AND r.member_id=m.id AND r.role_code='SALES_MANAGER') DESC,m.created_at,m.id LIMIT 1",p("tenant",c.tenantId()),UUID.class);if(ids.isEmpty())throw new ApiError(org.springframework.http.HttpStatus.CONFLICT,"PORTAL_NO_SERVICE_OWNER","企业尚未配置可处理工单的服务人员");return ids.getFirst();}
 private void revision(PortalAuthService.Context c,UUID ticket,String action,String reason){var t=SaasService.view(one("SELECT id,ticket_number,title,description,type_code,priority,status,resolution,version,created_at,updated_at FROM crm_ticket WHERE tenant_id=:tenant AND id=:id",p("tenant",c.tenantId(),"id",ticket)));db.update("INSERT INTO crm_ticket_revision(id,tenant_id,ticket_id,business_version,action,snapshot,reason,portal_account_id,actor_name_snapshot) VALUES(:revision,:tenant,:ticket,:version,:action,cast(:snapshot AS jsonb),:reason,:account,:name)",p("revision",UUID.randomUUID(),"tenant",c.tenantId(),"ticket",ticket,"version",t.get("version"),"action",action,"snapshot",body(t),"reason",reason,"account",c.accountId(),"name",c.displayName()));}
 public Object createTicket(PortalAuthService.Context c,TicketInput i,String key,UUID trace){return scoped(c,true,x->{UUID id=once(x,"ticket.create",key,i,()->{if(db.queryForObject("SELECT count(*) FROM crm_dictionary_item WHERE tenant_id=:tenant AND dictionary_type='TICKET_TYPE' AND item_code=:code AND active",p("tenant",x.tenantId(),"code",i.typeCode()),Integer.class)!=1)throw ApiError.bad("工单类型无效");UUID member=assignee(x),created=UUID.randomUUID();Map<String,Object> sla=builtinSla();var q=p("tenant",x.tenantId(),"year",LocalDate.now(ZoneId.of("Asia/Shanghai")).getYear());long seq=db.queryForObject("INSERT INTO crm_ticket_counter(tenant_id,ticket_year,next_value) VALUES(:tenant,:year,1) ON CONFLICT(tenant_id,ticket_year) DO UPDATE SET next_value=crm_ticket_counter.next_value+1 RETURNING next_value",q,Long.class);String number=P4Numbering.format(db,x.tenantId(),"TICKET",(int)q.get("year"),seq,"CS");db.update("INSERT INTO crm_ticket(id,tenant_id,ticket_number,title,description,customer_id,owner_member_id,assignee_member_id,requester_name,requester_email,priority,sla_snapshot,type_code,portal_created) VALUES(:id,:tenant,:number,:title,:body,:customer,:member,:member,:name,:email,:priority,cast(:sla AS jsonb),:type,true)",p("id",created,"tenant",x.tenantId(),"number",number,"title",text(i.title()),"body",text(i.description()),"customer",x.customerId(),"member",member,"name",x.displayName(),"email",x.email(),"priority",i.priority(),"sla",body(sla),"type",i.typeCode()));Instant now=Instant.now();db.update("INSERT INTO crm_ticket_sla_episode(id,tenant_id,ticket_id,cycle_no,first_response_due_at,resolution_due_at,state) VALUES(:id,:tenant,:ticket,1,:response,:resolution,'ACTIVE')",p("id",UUID.randomUUID(),"tenant",x.tenantId(),"ticket",created,"response",Timestamp.from(now.plusSeconds(minutes(sla,i.priority(),"responseMinutes")*60L)),"resolution",Timestamp.from(now.plusSeconds(minutes(sla,i.priority(),"resolutionMinutes")*60L))));revision(x,created,"PORTAL_CREATED","");auth.audit(x,"TICKET_CREATED","TICKET",created,trace);return created;});return ticket(x,id);});}
 public Object comment(PortalAuthService.Context c,UUID id,CommentInput i,String key,UUID trace){return scoped(c,true,x->{UUID result=once(x,"ticket.comment",key,p("ticket",id,"input",i),()->{var t=ticket(x,id);if(!Set.of("NEW","IN_PROGRESS","WAITING_CUSTOMER").contains(t.get("status")))throw ApiError.conflict("当前工单已结束，不能继续回复");if(((Number)t.get("version")).longValue()!=i.expectedVersion())throw ApiError.conflict("工单已变化，请刷新");db.update("INSERT INTO crm_ticket_comment(id,tenant_id,ticket_id,body,kind,portal_account_id,actor_name_snapshot) VALUES(:comment,:tenant,:ticket,:body,'PUBLIC_REPLY',:account,:name)",p("comment",UUID.randomUUID(),"tenant",x.tenantId(),"ticket",id,"body",text(i.body()),"account",x.accountId(),"name",x.displayName()));db.update("UPDATE crm_ticket SET version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id",p("tenant",x.tenantId(),"id",id));revision(x,id,"PORTAL_REPLIED","PUBLIC_REPLY");auth.audit(x,"TICKET_REPLIED","TICKET",id,trace);return id;});return ticket(x,result);});}
 public Object dictionaries(PortalAuthService.Context c){return scoped(c,false,x->p("ticketTypes",rows("SELECT item_code,label,position FROM crm_dictionary_item WHERE tenant_id=:tenant AND dictionary_type='TICKET_TYPE' AND active ORDER BY position,id",p("tenant",x.tenantId()))));}
 public Object articles(PortalAuthService.Context c,int page,int size,String q){page(page,size,q);return scoped(c,false,x->{var v=p("tenant",x.tenantId(),"q",text(q).toLowerCase(Locale.ROOT),"limit",size,"offset",((long)page-1)*size);var raw=rows("SELECT a.id,a.published_version,r.snapshot::text AS snapshot,c.name AS category FROM crm_knowledge_article a JOIN crm_knowledge_revision r ON r.tenant_id=a.tenant_id AND r.article_id=a.id AND r.business_version=a.published_version JOIN crm_knowledge_category c ON c.tenant_id=a.tenant_id AND c.id=a.category_id WHERE a.tenant_id=:tenant AND a.published_version IS NOT NULL AND a.status='PUBLISHED' ORDER BY a.updated_at DESC,a.id",v);var items=new ArrayList<Map<String,Object>>();for(var r:raw){var snap=object(r.get("snapshot"));String title=String.valueOf(snap.get("title")),body=String.valueOf(snap.get("body"));if(!v.get("q").equals("")&&!title.toLowerCase(Locale.ROOT).contains(String.valueOf(v.get("q")))&&!body.toLowerCase(Locale.ROOT).contains(String.valueOf(v.get("q"))))continue;items.add(p("id",r.get("id"),"title",title,"category",r.get("category"),"publishedVersion",r.get("publishedVersion")));}long offset=((long)page-1)*size;return new Page<>(items.subList((int)Math.min(offset,items.size()),(int)Math.min(offset+size,items.size())),page,size,items.size());});}
 public Object article(PortalAuthService.Context c,UUID id){return scoped(c,false,x->{var r=one("SELECT a.id,a.published_version,r.snapshot::text AS snapshot,c.name AS category FROM crm_knowledge_article a JOIN crm_knowledge_revision r ON r.tenant_id=a.tenant_id AND r.article_id=a.id AND r.business_version=a.published_version JOIN crm_knowledge_category c ON c.tenant_id=a.tenant_id AND c.id=a.category_id WHERE a.tenant_id=:tenant AND a.id=:id AND a.published_version IS NOT NULL AND a.status='PUBLISHED'",p("tenant",x.tenantId(),"id",id));var snap=object(r.get("snapshot"));return p("id",id,"title",snap.get("title"),"body",snap.get("body"),"category",r.get("category"),"publishedVersion",r.get("publishedVersion"));});}
 public Object upload(PortalAuthService.Context c,UUID ticket,String original,byte[] bytes,String key,UUID trace){String name=AttachmentService.filename(original),type=AttachmentService.fileType(name,bytes),digest=sha(bytes);UUID created=UUID.randomUUID();String object=storage.key(c.tenantId(),created);boolean[] stored={false};try{return scoped(c,true,x->{var t=ticket(x,ticket);if(!Set.of("NEW","IN_PROGRESS","WAITING_CUSTOMER").contains(t.get("status")))throw ApiError.conflict("结束的工单不能上传附件");UUID result=once(x,"ticket.attachment",key,p("ticket",ticket,"name",name,"sha256",digest),()->{var quota=db.queryForMap("SELECT t.attachment_bytes,p.storage_limit_bytes FROM sys_tenant t JOIN sys_plan p ON p.id=t.plan_id WHERE t.id=:tenant",p("tenant",x.tenantId()));if(((Number)quota.get("attachment_bytes")).longValue()+bytes.length>((Number)quota.get("storage_limit_bytes")).longValue())throw ApiError.conflict("附件容量已达到套餐上限");storage.put(object,bytes,type);stored[0]=true;db.update("INSERT INTO crm_attachment(id,tenant_id,customer_id,ticket_id,file_name,content_type,size_bytes,sha256,object_key,uploaded_by_portal_account_id) VALUES(:id,:tenant,:customer,:ticket,:name,:type,:size,:sha,:object,:account)",p("id",created,"tenant",x.tenantId(),"customer",x.customerId(),"ticket",ticket,"name",name,"type",type,"size",bytes.length,"sha",digest,"object",object,"account",x.accountId()));auth.audit(x,"ATTACHMENT_UPLOADED","ATTACHMENT",created,trace);return created;});return SaasService.view(one("SELECT id,file_name,content_type,size_bytes,sha256,created_at FROM crm_attachment WHERE tenant_id=:tenant AND id=:id AND ticket_id=:ticket",p("tenant",x.tenantId(),"id",result,"ticket",ticket)));});}catch(RuntimeException e){if(stored[0])try{storage.delete(object);}catch(Exception ignored){}throw e;}}
 public AttachmentService.Download download(PortalAuthService.Context c,UUID id,UUID trace){return scoped(c,false,x->{var r=one("SELECT x.* FROM crm_attachment x JOIN crm_ticket t ON t.tenant_id=x.tenant_id AND t.id=x.ticket_id WHERE x.tenant_id=:tenant AND t.customer_id=:customer AND x.id=:id AND x.status='READY'",p("tenant",x.tenantId(),"customer",x.customerId(),"id",id));byte[] bytes=storage.get(String.valueOf(r.get("object_key")));if(bytes.length!=((Number)r.get("size_bytes")).longValue()||!sha(bytes).equals(r.get("sha256")))throw new ApiError(org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE,"ATTACHMENT_INTEGRITY_ERROR","文件校验未通过");auth.audit(x,"ATTACHMENT_DOWNLOADED","ATTACHMENT",id,trace);return new AttachmentService.Download(String.valueOf(r.get("file_name")),String.valueOf(r.get("content_type")),bytes);});}
 private static String sha(byte[] data){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(data));}catch(Exception e){throw new IllegalStateException(e);}}
}
